const filePath = path.join(__dirname, '..', 'src', 'core', 'exercise-catalog.ts');
let content = fs.readFileSync(filePath, 'utf8');

// Check for marker to avoid double insertion
if (content.includes('РАСШИРЕННАЯ БАЗА')) {
  console.log('Extended exercises already present. Skipping insertion.');
  process.exit(0);
}

// The EXERCISE_CATALOG array closes with ]; right before the SUBSTITUTION_MAP export
// Find the pattern: "];\n\nexport const SUBSTITUTION_MAP" and insert before ];
const marker = '];\n\nexport const SUBSTITUTION_MAP';
const idx = content.indexOf(marker);
if (idx === -1) {
  console.error('Could not find SUBSTITUTION_MAP after EXERCISE_CATALOG close.');
  process.exit(1);
}

// Insert new exercises before the ];
content = content.slice(0, idx) + newExercises + content.slice(idx);
fs.writeFileSync(filePath, content, 'utf8');
console.log('Successfully inserted ~180 new exercises inside EXERCISE_CATALOG!');
console.log('File size:', (content.length / 1024).toFixed(0), 'KB');
